import math

def kmeans_step(points, centroids):
    groups = [[] for _ in centroids]
    for p in points:
        nearest = min(range(len(centroids)), key=lambda j: math.dist(p, centroids[j]))
        groups[nearest].append(p)
    new = []
    for c, group in zip(centroids, groups):
        if group:
            new.append([sum(p[0] for p in group) / len(group), sum(p[1] for p in group) / len(group)])
        else:
            new.append(c)
    return new

